class Solution {
public:
    int longestPalindrome(string s) {
        map<char, int> cnt;
        for (char c : s) cnt[c]++;
        int len = 0;
        bool odd = false;
        for (auto& [c, n] : cnt) {
            len += n / 2 * 2;
            if (n % 2) odd = true;
        }
        return len + (odd ? 1 : 0);
    }
};
